async def backfill_with_verification(db: AsyncSession, data: list[dict]) -> None:
    for item in data:
        db.add(MyModel(**item))
        await db.flush()
        try:
            # Verify before committing
            existing = await db.execute(
                select(MyModel).where(MyModel.unique_field == item["unique_field"])
            )
            if existing.scalars().first():
                raise ValueError("Duplicate detected")
        except Exception:
            await db.rollback()
            raise
    await db.commit()

